 p=subprocess.run([rc,'thread',*x],stdin=subprocess.DEVNULL,capture_output=True,text=True,env=e,timeout=20);return p.returncode,p.stdout
def drive(q):
 p=subprocess.run([a[0],c],input='' if q is None else json.dumps(q),capture_output=True,text=True,env=e);return p.returncode,json.loads(p.stdout)
if c=='version':r,o=drive(None)
elif c=='start':
 if os.path.exists(f) or runs():no('not_fresh')
