   k,out=room('show',d['thread']);v=json.loads(out) if k==0 else {};left+=v.get('archived') is not True;inp=inp and v.get('projectId')==pj
  else:left+=d.get('archived') is not True
 r,o=0,{'left_running':left,'in_project':inp,'runs':len(runs())}
print(json.dumps(o));sys.exit(r)

